                        routes[i] = new_ri
                        routes[j] = new_rj
                        if not routes[i]:
                            routes.pop(i)
                        improved = True
                        break
                if improved:
                    break

    # cleanup empties, final 2-opt
    routes = [two_opt(r) for r in routes if r]

    # final validation/repair to guarantee exact cover once
    present = {}
    for r in routes:
        for c in r:
            present[c] = present.get(c, 0) + 1

    if any(present.get(c, 0) != 1 for c in customers):
        # fallback: rebuild by greedy insertion into best feasible routes
        routes = []
        for c in ordered:
            placed = False
            best_r = -1
            best_pos = -1
            best_delta = None
            for ri, r in enumerate(routes):
                if route_demand(r) + demand_get(c) > capacity:
                    continue
                base = route_cost(r)
                for i in range(len(r) + 1):
                    cand = r[:i] + [c] + r[i:]
                    delta = route_cost(cand) - base
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = ri
                        best_pos = i
            if best_r == -1:
                routes.append([c])
            else:
                r = routes[best_r]
                routes[best_r] = r[:best_pos] + [c] + r[best_pos:]
        routes = [two_opt(r) for r in routes if r]

    return routes
